import struct,bisect,collections
d=open('/home/test/t508n/work/stock_Image_full.bin','rb').read(); C=0xffffffc07ffff000
# parse map addresses T/t
addrs=[]
for line in open('/home/test/t508n/work/System.map',errors='ignore'):
 p=line.split(); 
 if len(p)>=2 and p[1] in ('T','t','W','w'):
  addrs.append(int(p[0],16))
addrs.sort()
hist=collections.Counter(); exact=[]; near=[]
for F in range(0x1000,0x1600000,4):
 w=struct.unpack_from('<I',d,F)[0]
 if (w>>26)==0x25:
  imm=w & ((1<<26)-1)
  if imm & (1<<25): imm-=1<<26
  T=F+C+(imm<<2)
  i=bisect.bisect_left(addrs,T)
  best=1<<60; ba=None
  for j in (i-1,i,i+1):
   if 0<=j<len(addrs):
    delta=T-addrs[j]
    if abs(delta)<abs(best): best=delta;ba=addrs[j]
  if abs(best)<=8: exact.append((F,T,best,ba))
  hist[best//4*4]+=1
for delta in sorted(hist,key=lambda x:(abs(x),x))[:30]: print(delta,hist[delta])
print('near-zero total',sum(v for d,v in hist.items() if abs(d)<=8))
print('exact samples',len(exact))
for row in exact[:20]: print(hex(row[0]),'->',hex(row[1]),'sym',hex(row[3]),'delta',row[2])
PY"}

