import struct
d=open('/home/test/t508n/work/stock_Image_full.bin','rb').read(); base=0xffffffc080000000; C=0xffffffc07ffff000
# scan for prologue sub sp, imm ; mrs sp_el0 within +/-0x2000 of map addr
for name,addr in [('kobject_add',0xffffffc08104bc80),('kobject_set_name_vargs',0xffffffc08104baa8),('kobject_move',0xffffffc08104b908),('kobject_rename',0xffffffc08104b7b0)]:
 off0=addr-base+0x1000
 print(name,hex(off0))
 for off in range(off0-0x1000,off0+0x1000,4):
  w=struct.unpack_from('<I',d,off)[0]
  # sub sp, sp, #imm encoded 0xd1xxxxxx? bit 31..24 =11010001? d101xxxx
  if (w>>24)==0xd1 and ((w>>10)&0x1f)==31 and ((w>>5)&0x1f)==31:
   imm=(w>>10)&0xfff
   nxt=struct.unpack_from('<I',d,off+4)[0]
   if nxt==0xd5384108 or nxt==0xd5384101 or nxt==0xf800865e or (nxt&0xff000000)==0xa9000000:
    print(' prologue candidate',hex(off),'vaddr',hex(off+C),'w',hex(w),'imm',hex(imm),'next',hex(nxt))
PY"}

