static int __init __apply_alternatives_multi_stop(void *unused)
{
	/* We always have a CPU 0 at this point (__init) */
	if (smp_processor_id()) {
		/*
		 * T508N: 跨 cluster cache 一致性不完善, 二级核可能读不到
		 * all_alternatives_applied。加超时兜底, 超时后 isb 返回,
		 * 避免永久卡住 (alternative 是可选优化, 未 patch 代码也安全)。
		 */
		unsigned long loops = 0;
		while (!all_alternatives_applied && loops++ < 10000000UL)
			cpu_relax();
		{
			extern void t508n_paint_bar(int x, int y, int w, int h);
			t508n_paint_bar(80, 180, 24, 10); /* 二级核退出while */
		}
		isb();
	} else {
		extern void t508n_paint_bar(int x, int y, int w, int h);
		DECLARE_BITMAP(remaining_capabilities, ARM64_NCAPS);

		bitmap_complement(remaining_capabilities, boot_cpucaps,
				  ARM64_NCAPS);

		BUG_ON(all_alternatives_applied);
		__apply_alternatives(&kernel_alternatives, false,
				     remaining_capabilities);
		t508n_paint_bar(8, 180, 24, 10); /* __apply_alternatives 返回 */
		/* Barriers provided by the cache flushing */
		all_alternatives_applied = 1;
		t508n_paint_bar(44, 180, 24, 10); /* 置位后 */
		t508n_mark_row(180, 7);	/* 行号标注: 第7行 */
		/* T508N: 显式刷到 PoC, 确保二级核可见 */
		dcache_clean_poc((unsigned long)&all_alternatives_applied,
				 (unsigned long)&all_alternatives_applied +
				 sizeof(all_alternatives_applied));
