/*
 * T508N: 在 SMP 上线前 patch LSE atomics (最小实验)。
 * 跳过完整 apply_alternatives_all 时, ARM64_HAS_LSE_ATOMICS 是 SCOPE_SYSTEM,
 * 不会被 patch, 内核整体退化成 LL/SC, 疑似导致间歇性卡死。
 * 所有 T770 CPU (A55/A76) 都支持 LSE, boot CPU 判断即可; SMP 未上线, 全局 patch 安全。
 */
void __init t508n_apply_lse_early(void)
{
	u64 isar0;
	DECLARE_BITMAP(caps, ARM64_NCAPS);

	isar0 = read_sanitised_ftr_reg(SYS_ID_AA64ISAR0_EL1);
	if (!cpuid_feature_extract_unsigned_field(isar0, ID_AA64ISAR0_EL1_ATOMIC_SHIFT))
		return;

	pr_info("T508N: early-patching LSE atomics\n");

	set_bit(ARM64_HAS_LSE_ATOMICS, system_cpucaps);
	bitmap_clear(caps, 0, ARM64_NCAPS);
	set_bit(ARM64_HAS_LSE_ATOMICS, caps);
	__apply_alternatives(&kernel_alternatives, false, caps);
}

#ifdef CONFIG_MODULES
void apply_alternatives_module(void *start, size_t length)
{
	struct alt_region region = {
		.begin	= start,
		.end	= start + length,
	};
	DECLARE_BITMAP(all_capabilities, ARM64_NCAPS);

	bitmap_fill(all_capabilities, ARM64_NCAPS);

	__apply_alternatives(&region, true, &all_capabilities[0]);
}
#endif

noinstr void alt_cb_patch_nops(struct alt_instr *alt, __le32 *origptr,
			       __le32 *updptr, int nr_inst)
{
	for (int i = 0; i < nr_inst; i++)
		updptr[i] = cpu_to_le32(aarch64_insn_gen_nop());
}
EXPORT_SYMBOL(alt_cb_patch_nops);
