import subprocess,re,os
OBJ='/home/test/t508n/arm-gnu-toolchain-13.2.Rel1-x86_64-aarch64-none-linux-gnu/bin/aarch64-none-linux-gnu-objdump'
mods={
 'hs':('/home/test/t508n/work/fs/vendor_dlkm_a/lib/modules/phy-sprd-qogirn6pro.ko',['sprd_hsphy_init','sprd_hsphy_shutdown']),
 'ss':('/home/test/t508n/work/fs/vendor_dlkm_a/lib/modules/phy-sprd-usb31-qogirn6pro.ko',['sprd_ssphy_init','sprd_ssphy_shutdown','sprd_ssphy_reset_core','usb_config_4_cts']),
}
def parse_dis(path,fn):
 out=subprocess.check_output([OBJ,'-d',f'--disassemble={fn}',path],stderr=subprocess.DEVNULL).decode(errors='ignore')
 ins=[]
 for l in out.splitlines():
  m=re.match(r'\s*([0-9a-f]+):\s+([0-9a-f]+)\s+(.*)',l)
  if m: ins.append((int(m.group(1),16),m.group(3)))
 return ins

def backward_args(ins,i,window=30):
 # returns dict w regs/x regs and field descriptions
 d={}
 stack={}
 for j in range(i-1,max(-1,i-window),-1):
  t=ins[j][1]
  # skip branch target lines? t includes only asm text
  m=re.search(r'mov\t(w(\d+)|x(\d+)),\s*#(0x[0-9a-f]+|-?\d+)',t)
  if m:
   reg=m.group(1); val=int(m.group(4),0); d[reg]=val
  m=re.search(r'movk\t(w|x)(\d+),\s*#(0x[0-9a-f]+)',t)
  if m:
   reg=m.group(1)+m.group(2); val=int(m.group(3),0)
   if reg in d and (m.group(1)=='w'): d[reg]=(d[reg]&0xffff)|(val<<16)
  m=re.search(r'mov\t(w(\d+)),\s*wzr',t)
  if m: d[m.group(1)]=0
  m=re.search(r'ldr\t(w\d+),\s*\[(x\d+),\s*#(-?0x[0-9a-f]+|-?\d+)\]',t)
  if m:
   # field load from priv; mark as FIELD and keep base
   d[m.group(1)]=('FIELD',m.group(2),int(m.group(3),0))
  m=re.search(r'str\t(w\d+),\s*\[sp,\s*#(-?0x[0-9a-f]+|-?\d+)\]',t)
  if m: stack[m.group(1)]=m.group(2)
  m=re.search(r'add\tx(\d+),\s*sp,\s*#(-?0x[0-9a-f]+|-?\d+)',t)
  if m: d['x'+m.group(1)]=('SP',int(m.group(2),0))
  m=re.search(r'orr\tw(\d+),\s*w(\d+),\s*#(0x[0-9a-f]+)',t)
  if m:
   dst='w'+m.group(1); src=d.get('w'+m.group(2),0); val=int(m.group(3),0)
   if isinstance(src,int): d[dst]=src|val
   else: d[dst]=f'FIELD_OR_{val:#x}'
  # ldr x0,[x19,#imm] direct regmap
  m=re.search(r'ldr\tx(\d+),\s*\[(x\d+),\s*#(0x[0-9a-f]+|-?\d+)\]',t)
  if m:
   base='x'+m.group(2); off=int(m.group(3),0); d['x'+m.group(1)]=('REGMAP',base,off)
  if re.match(r'bl\t',t): break
 return d,stack
for tag,(path,fns) in mods.items():
 print('\n############',tag)
 for fn in fns:
  ins=parse_dis(path,fn)
  print('\n===== ',fn)
  for i,(a,t) in enumerate(ins):
   if t.startswith('bl\t') and any(x in t for x in ['regmap_update_bits_base','regmap_write','regmap_read','regulator_enable','sprd_usbm_','ptn38003a_mode_usb32_set','usleep_range','msleep']):
    d,st=backward_args(ins,i)
    # simplify regmap source
    x0=d.get('x0')
    print(f'{a:04x} {t.strip():45s} x0={x0} w1={d.get("w1")} w2={d.get("w2")} w3={d.get("w3")} w0={d.get("w0")} stack={st}')
PY"}

