// SPDX-License-Identifier: GPL-2.0
/*
 * Minimal sprd_usbm replacement.
 * Stock sprd_usbm.ko exports exactly these hooks; for ADB/peripheral bring-up
 * the full notifier/event state machine is not needed.
 */
#include <linux/export.h>
#include <linux/mutex.h>
#include "sprd_usbm_min.h"

static DEFINE_MUTEX(sprd_usbm_mutex);
static bool usb_event_active = true;
static bool hsphy_on;
static bool ssphy_on;

void sprd_usbm_mutex_lock(void)
{
	mutex_lock(&sprd_usbm_mutex);
}
EXPORT_SYMBOL_GPL(sprd_usbm_mutex_lock);

void sprd_usbm_mutex_unlock(void)
{
	mutex_unlock(&sprd_usbm_mutex);
}
EXPORT_SYMBOL_GPL(sprd_usbm_mutex_unlock);

bool sprd_usbm_event_is_active(void)
{
	return usb_event_active;
}
EXPORT_SYMBOL_GPL(sprd_usbm_event_is_active);

void sprd_usbm_event_set_active(bool on)
{
	usb_event_active = on;
}
EXPORT_SYMBOL_GPL(sprd_usbm_event_set_active);

int sprd_usbm_hsphy_set_onoff(bool on)
{
	hsphy_on = on;
	return 0;
