// SPDX-License-Identifier: GPL-2.0
/*
 * T508N minimal SS USB3.1 PHY driver, reconstructed from:
 *   work/fs/vendor_dlkm_a/lib/modules/phy-sprd-usb31-qogirn6pro.ko
 *   (function sprd_ssphy_probe/init/shutdown/reset_core)
 *
 * This is a bring-up skeleton: only the register tables found by disassembly
 * are implemented. BC1P2 / typec / PD / PTN38003A are deliberately omitted.
 */
#include <linux/io.h>
#include <linux/module.h>
#include <linux/of.h>
#include <linux/of_address.h>
#include <linux/phy/phy.h>
#include <linux/platform_device.h>
#include <linux/regmap.h>
#include <linux/mfd/syscon.h>
#include <linux/regulator/consumer.h>
#include <linux/delay.h>

#include "sprd_usbm_min.h"

struct sprd_ssphy {
	struct device *dev;
	void __iomem *glb;		/* phy_glb_regs */
	struct regmap *aon;		/* sprd,syscon-aon-apb */
	struct regmap *ana;		/* sprd,syscon-ana-g0l */
	struct regmap *ipa_apb;		/* sprd,syscon-ipa-apb */
	struct regmap *ipadispc;	/* sprd,syscon-ipa-dispc1-glb-apb */
	struct regmap *ipa_dp;		/* sprd,syscon-ipa-usb31-dp */
	struct regmap *ipa_dptx;	/* sprd,syscon-ipa-usb31-dptx */
	struct regmap *pmic;		/* sprd,ump962x-syscon */
	struct regulator *vdd;
	u32 vdd_uv;
	u32 ctl5;
	u32 ctl6;
	u32 hs_host_eye;
	u32 hs_dev_eye;
	bool inited;
};

static int sprd_ssphy_init(struct phy *phy)
{
	struct sprd_ssphy *p = phy_get_drvdata(phy);
	int ret = 0;

	if (p->inited)
		return 0;

	sprd_usbm_mutex_lock();

	/* ptn38003a_mode_usb32_set(1) omitted; redriver not present on all boards */
	if (p->vdd) {
		ret = regulator_enable(p->vdd);
		if (ret)
			goto out;
	}

	sprd_usbm_ssphy_set_onoff(true);

	if (sprd_usbm_event_is_active() && !sprd_usbm_hsphy_get_onoff()) {
		regmap_update_bits(p->glb, 0x004, 0x1300, 0x1300);
		regmap_update_bits(p->glb, 0x138, 0x1400, 0x1400);
		regmap_update_bits(p->glb, 0x350, 0x3, 0x0);
		regmap_update_bits(p->aon, 0x01c, BIT(0), 0x0);
		regmap_update_bits(p->glb, 0x190, BIT(4), 0x0);
		regmap_update_bits(p->glb, 0x204, BIT(24), BIT(24));
		regmap_update_bits(p->aon, 0x004, BIT(16), BIT(16));
		regmap_write(p->aon, 0x010, p->hs_host_eye);
	}

	regmap_update_bits(p->glb, 0xd14, BIT(2), BIT(2));
	/* aon 0x004 read, then write (val | 0x5) */
	{
		u32 v;
		regmap_read(p->aon, 0x004, &v);
		regmap_write(p->aon, 0x004, v | 0x5);
	}
	regmap_update_bits(p->glb, 0x138, BIT(22), BIT(22));
	regmap_update_bits(p->glb, 0xd14, BIT(1), 0x0);
	regmap_update_bits(p->glb, 0xd14, BIT(2), BIT(2));

	/* wait ipa_dp 0x74 bit2 */
	if (read_poll_timeout(regmap_read, ret,
			      !ret && (v & BIT(2)), 1000, 500000, false,
			      p->ipa_dp, 0x74, &v)) {
		dev_err(p->dev, "SSPHY 0x74 bit2 timeout\n");
		ret = -ETIMEDOUT;
		goto out;
	}

	regmap_read(p->ipa_dp, 0xc08, &v);
	regmap_write(p->ipa_dp, 0xc08, v | BIT(0));

	/* Direct phy_glb writes */
	writel_relaxed(readl_relaxed(p->glb + 0x10) & 0x3f, p->glb + 0x2c);
	writel_relaxed(readl_relaxed(p->glb + 0x20) | 0x6, p->glb + 0x20);
	writel_relaxed(0x0003d090, p->glb + 0x24);
	writel_relaxed(0xffff, p->glb + 0x08);
	writel_relaxed(readl_relaxed(p->glb + 0x04) | 0x3, p->glb + 0x04);
	regmap_read(p->aon, 0x004, &v);
	writel_relaxed((readl_relaxed(p->glb + 0x14) & ~0x1f) |
		       (v & BIT(10) ? 0x17 : 0x13), p->glb + 0x14);

	p->inited = true;
out:
	sprd_usbm_mutex_unlock();
	return ret;
}

static int sprd_ssphy_exit(struct phy *phy)
{
	struct sprd_ssphy *p = phy_get_drvdata(phy);

	if (!p->inited)
		return 0;

	sprd_usbm_mutex_lock();
	regmap_update_bits(p->ipa_dp, 0x01c, BIT(0), BIT(0));
	regmap_update_bits(p->glb, 0x204, BIT(24), 0x0);
	regmap_update_bits(p->glb, 0x190, BIT(4), BIT(4));
	regmap_update_bits(p->glb, 0x350, 0x3, 0x3);
	regmap_update_bits(p->glb, 0x138, 0x1400, 0x0);
	regmap_update_bits(p->glb, 0x004, 0x300, 0x0);
	regmap_update_bits(p->glb, 0xd14, BIT(2), 0x0);
	regmap_update_bits(p->glb, 0xd14, BIT(1), BIT(1));
	sprd_usbm_ssphy_set_onoff(false);
	if (p->vdd)
		regulator_disable(p->vdd);
	sprd_usbm_mutex_unlock();
	p->inited = false;

	return 0;
}

static const struct phy_ops sprd_ssphy_ops = {
	.init		= sprd_ssphy_init,
	.exit		= sprd_ssphy_exit,
	.owner		= THIS_MODULE,
};

static int sprd_ssphy_probe(struct platform_device *pdev)
{
	struct device *dev = &pdev->dev;
	struct phy_provider *provider;
	struct phy *phy;
	struct sprd_ssphy *p;
	struct resource *res;

	p = devm_kzalloc(dev, sizeof(*p), GFP_KERNEL);
	if (!p)
		return -ENOMEM;
	p->dev = dev;

	res = platform_get_resource_byname(pdev, IORESOURCE_MEM, "phy_glb_regs");
	p->glb = devm_ioremap_resource(dev, res);
	if (IS_ERR(p->glb))
		return PTR_ERR(p->glb);

	p->aon      = syscon_regmap_lookup_by_phandle(dev->of_node, "sprd,syscon-aon-apb");
	p->ana      = syscon_regmap_lookup_by_phandle(dev->of_node, "sprd,syscon-ana-g0l");
	p->ipa_apb  = syscon_regmap_lookup_by_phandle(dev->of_node, "sprd,syscon-ipa-apb");
	p->ipadispc = syscon_regmap_lookup_by_phandle(dev->of_node, "sprd,syscon-ipa-dispc1-glb-apb");
	p->ipa_dp   = syscon_regmap_lookup_by_phandle(dev->of_node, "sprd,syscon-ipa-usb31-dp");
	p->ipa_dptx = syscon_regmap_lookup_by_phandle(dev->of_node, "sprd,syscon-ipa-usb31-dptx");
	if (IS_ERR(p->aon) || IS_ERR(p->ana) || IS_ERR(p->ipa_apb) ||
	    IS_ERR(p->ipadispc) || IS_ERR(p->ipa_dp) || IS_ERR(p->ipa_dptx))
		return -ENODEV;

	of_property_read_u32(dev->of_node, "sprd,vdd-voltage", &p->vdd_uv);
	p->vdd = devm_regulator_get_optional(dev, "vdd");
	if (!IS_ERR(p->vdd))
		regulator_set_voltage(p->vdd, p->vdd_uv, p->vdd_uv);
	else
		p->vdd = NULL;

	of_property_read_u32(dev->of_node, "sprd,ssphy-ctl5-eye-pattern", &p->ctl5);
	of_property_read_u32(dev->of_node, "sprd,ssphy-ctl6-eye-pattern", &p->ctl6);
	of_property_read_u32(dev->of_node, "sprd,hsphy-host-eye-pattern", &p->hs_host_eye);
	of_property_read_u32(dev->of_node, "sprd,hsphy-device-eye-pattern", &p->hs_dev_eye);

	phy = devm_phy_create(dev, NULL, &sprd_ssphy_ops);
	if (IS_ERR(phy))
		return PTR_ERR(phy);
	phy_set_drvdata(phy, p);

	provider = devm_of_phy_provider_register(dev, of_phy_simple_xlate);
	return PTR_ERR_OR_ZERO(provider);
}

static const struct of_device_id sprd_ssphy_match[] = {
	{ .compatible = "sprd,qogirn6pro-ssphy" },
	{ }
};
MODULE_DEVICE_TABLE(of, sprd_ssphy_match);

static struct platform_driver sprd_ssphy_driver = {
	.probe = sprd_ssphy_probe,
	.driver = {
		.name = "sprd-ssphy",
		.of_match_table = sprd_ssphy_match,
	},
};
module_platform_driver(sprd_ssphy_driver);

MODULE_DESCRIPTION("T508N minimal SPRD UMS9620 SS USB3.1 PHY");
MODULE_LICENSE("GPL v2");
