		regmap_update_bits(p->aon, 0x350, 0x3, 0x0);
		regmap_update_bits(p->ipa_dptx, 0x01c, BIT(0), BIT(0));
		regmap_update_bits(p->aon, 0x190, BIT(4), BIT(4));
		regmap_update_bits(p->aon, 0x204, BIT(24), BIT(24));
		regmap_update_bits(p->ipa_dptx, 0x004, BIT(16), BIT(16));
		regmap_write(p->ipa_dptx, 0x010, p->hs_host_eye);
