	regmap_read(p->ana, 0x004, &v);
	regmap_write(p->ana, 0x004, v | 0x5);
	regmap_update_bits(p->aon, 0x138, BIT(22), BIT(22));
	regmap_update_bits(p->aon, 0xd14, BIT(1), 0x0);
	regmap_update_bits(p->aon, 0xd14, BIT(2), BIT(2));

