static int ums9620_ipa_clk_probe(struct platform_device *pdev)
{
	int ret = sprd_clk_regmap_init(pdev, &(struct sprd_clk_desc){});
	if (ret)
		return ret;
	return sprd_clk_probe(&pdev->dev, &ums9620_ipa_clk_hws);
}

static int ums9620_ipaapb_gate_probe(struct platform_device *pdev)
{
	int ret = sprd_clk_regmap_init(pdev, &ums9620_ipaapb_gate_desc);
	if (ret)
		return ret;
	return sprd_clk_probe(&pdev->dev, &ums9620_ipaapb_gate_hws);
}

static int ums9620_ipadispc_gate_probe(struct platform_device *pdev)
{
	int ret = sprd_clk_regmap_init(pdev, &ums9620_ipadispc_gate_desc);
	if (ret)
		return ret;
	return sprd_clk_probe(&pdev->dev, &ums9620_ipadispc_gate_hws);
}

static const struct of_device_id ums9620_clk_match[] = {
	{ .compatible = "sprd,ums9620-ipaapb-gate", .data = ums9620_ipaapb_gate_probe },
	{ .compatible = "sprd,ums9620-ipadispc-gate", .data = ums9620_ipadispc_gate_probe },
	{ .compatible = "sprd,ums9620-ipa-clk", .data = ums9620_ipa_clk_probe },
	{ }
};
MODULE_DEVICE_TABLE(of, ums9620_clk_match);

static int ums9620_clk_probe(struct platform_device *pdev)
{
	const struct of_device_id *m;
	int (*fn)(struct platform_device *);

	m = of_match_device(ums9620_clk_match, &pdev->dev);
	if (!m || !m->data)
		return -ENODEV;
	fn = m->data;
	return fn(pdev);
}

static struct platform_driver ums9620_clk_driver = {
	.probe = ums9620_clk_probe,
	.driver = {
		.name = "ums9620-clk",
		.of_match_table = ums9620_clk_match,
	},
};
module_platform_driver(ums9620_clk_driver);

MODULE_DESCRIPTION("T508N minimal UMS9620 USB clocks");
MODULE_LICENSE("GPL v2");
