 * IRQ 关、无调度器) 提前 patch LSE atomics。
 * 跳过完整 apply_alternatives_all 时, ARM64_HAS_LSE_ATOMICS 是 SCOPE_SYSTEM
 * 不会被 patch, 内核退化成 LL/SC; 而只 patch LSE 若不失效 I-cache, boot CPU
 * 会混用 LL/SC(旧I-cache) 与 LSE(新取指) 导致竞态。
 * 这里 patch 后显式 __flush_icache_range (ic ivau, 原厂式) 失效 I-cache。
 */
void __init t508n_apply_lse_early(void)
{
	u64 isar0;
	DECLARE_BITMAP(caps, ARM64_NCAPS);

	isar0 = read_sanitised_ftr_reg(SYS_ID_AA64ISAR0_EL1);
	if (!cpuid_feature_extract_unsigned_field(isar0, ID_AA64ISAR0_EL1_ATOMIC_SHIFT))
		return;

	pr_info("T508N: early-patching LSE atomics\n");

	set_bit(ARM64_HAS_LSE_ATOMICS, system_cpucaps);
	bitmap_clear(caps, 0, ARM64_NCAPS);
	set_bit(ARM64_HAS_LSE_ATOMICS, caps);
	__apply_alternatives(&kernel_alternatives, false, caps);

	/* 原厂式: ic ivau 按 VA 失效整个内核 text (单核早期, 无需 IPI) */
	caches_clean_inval_pou((unsigned long)_stext, (unsigned long)_etext);
	isb();

	/* ✅ 标记: LSE early patch 通过 */
	{
		extern void t508n_pass(int y);
		t508n_pass(140);
	}
}

